CREATE TABLE paths (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, teacher_id INTEGER NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (teacher_id) REFERENCES users(id)); CREATE TABLE path_courses (path_id INTEGER NOT NULL, course_id INTEGER NOT NULL, position INTEGER NOT NULL, PRIMARY KEY (path_id, course_id), FOREIGN KEY (path_id) REFERENCES paths(id) ON DELETE CASCADE, FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE);
